import type { MedicineLookupResult } from "./types";

/**
 * Verified medicine information lookup.
 * 1. Normalize the name with the U.S. National Library of Medicine RxNorm API (handles typos, brands, "paracetamol").
 * 2. Fetch the official drug label from the U.S. FDA (openFDA).
 * Nothing here is generated by AI; when no label is found we say so.
 */

const RXNAV = "https://rxnav.nlm.nih.gov/REST";
const OPENFDA = "https://api.fda.gov/drug/label.json";
const TIMEOUT_MS = 8000;
const SECTION_LIMIT = 1100;

const SECTION_FIELDS: Record<string, string[]> = {
  purpose: ["purpose"],
  uses: ["indications_and_usage"],
  boxedWarning: ["boxed_warning"],
  warnings: ["warnings", "warnings_and_cautions", "warnings_and_precautions"],
  doNotUse: ["do_not_use", "contraindications"],
  askDoctor: ["ask_doctor", "ask_doctor_or_pharmacist"],
  stopUse: ["stop_use"],
  sideEffects: ["adverse_reactions"],
  precautions: ["precautions", "general_precautions"],
  pregnancy: ["pregnancy_or_breast_feeding", "pregnancy"],
  interactions: ["drug_interactions"],
};

export function sanitizeMedicineName(raw: string): string {
  return raw
    .normalize("NFKC")
    .replace(/[^\p{L}\p{N}\s\-+./]/gu, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 80);
}

/** Drop strengths/forms ("650", "500mg", "tablet") so "Dolo 650" searches as "dolo". */
function coreName(name: string) {
  return name
    .toLowerCase()
    .replace(/\b\d+(\.\d+)?\s*(mg|mcg|g|ml|%|iu)?\b/g, " ")
    .replace(/\b(tablets?|tabs?|capsules?|caps?|syrup|suspension|injection|cream|gel|drops?|ointment|forte|plus)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function levenshtein(a: string, b: string) {
  const dp: number[] = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let prev = dp[0] ?? 0;
    dp[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = dp[j] ?? 0;
      dp[j] = Math.min((dp[j] ?? 0) + 1, (dp[j - 1] ?? 0) + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return dp[b.length] ?? 0;
}

export function isCloseMatch(query: string, candidate: string) {
  const q = query.toLowerCase().trim();
  const c = candidate.toLowerCase().trim();
  if (!q || !c) return false;
  if (q === c) return true;
  return levenshtein(q, c) <= Math.max(1, Math.floor(q.length * 0.2));
}

async function getJson(url: string): Promise<unknown | null> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  try {
    const res = await fetch(url, { signal: controller.signal, headers: { accept: "application/json" } });
    if (res.status === 404) return null;
    if (!res.ok) throw new Error(`Medicine source returned ${res.status}`);
    return await res.json();
  } finally {
    clearTimeout(timer);
  }
}

type RxCandidate = { rxcui?: string; name?: string };

/** Returns active-ingredient names RxNorm associates with the term, or [] if no confident match. */
async function normalizeWithRxNorm(term: string): Promise<string[]> {
  const data = (await getJson(
    `${RXNAV}/approximateTerm.json?term=${encodeURIComponent(term)}&maxEntries=6`,
  )) as { approximateGroup?: { candidate?: RxCandidate[] } } | null;
  const candidates = data?.approximateGroup?.candidate ?? [];
  const match = candidates.find((c) => c.rxcui && c.name && isCloseMatch(term, c.name));
  if (!match?.rxcui) return [];

  const related = (await getJson(`${RXNAV}/rxcui/${match.rxcui}/related.json?tty=IN`)) as {
    relatedGroup?: { conceptGroup?: { conceptProperties?: { name?: string }[] }[] };
  } | null;
  const names =
    related?.relatedGroup?.conceptGroup?.flatMap((g) => g.conceptProperties ?? []).map((p) => p.name ?? "") ?? [];
  const cleaned = names.filter(Boolean);
  return cleaned.length ? cleaned : [match.name!.toLowerCase()];
}

type FdaLabel = Record<string, unknown> & {
  set_id?: string;
  effective_time?: string;
  openfda?: {
    brand_name?: string[];
    generic_name?: string[];
    manufacturer_name?: string[];
    product_type?: string[];
    route?: string[];
  };
};

async function searchFda(ingredients: string[], rawTerm: string): Promise<FdaLabel[]> {
  const q = (v: string) => encodeURIComponent(`"${v}"`);
  const parts: string[] = [];
  const [only] = ingredients;
  if (ingredients.length === 1 && only) {
    parts.push(`openfda.generic_name:${q(only)}`, `openfda.substance_name:${q(only)}`);
  } else if (ingredients.length > 1) {
    parts.push(`(${ingredients.map((i) => `openfda.substance_name:${q(i)}`).join("+AND+")})`);
  }
  parts.push(`openfda.brand_name:${q(rawTerm)}`);
  const data = (await getJson(`${OPENFDA}?search=${parts.join("+")}&limit=10`)) as { results?: FdaLabel[] } | null;
  return data?.results ?? [];
}

function pickBest(labels: FdaLabel[], ingredients: string[], rawTerm: string): FdaLabel | null {
  if (!labels.length) return null;
  const want = ingredients.join(" and ").toLowerCase();
  // A label only counts when its generic or brand name genuinely matches; content richness breaks ties.
  const nameScore = (l: FdaLabel) => {
    const generic = (l.openfda?.generic_name?.[0] ?? "").toLowerCase();
    const brand = (l.openfda?.brand_name?.[0] ?? "").toLowerCase();
    let s = 0;
    if (want && generic === want) s += 5;
    else if (want && ingredients.every((i) => generic.includes(i.toLowerCase()))) s += 3;
    if (brand && isCloseMatch(rawTerm, brand)) s += 4;
    return s;
  };
  const score = (l: FdaLabel) => {
    let s = nameScore(l);
    if (l["indications_and_usage"]) s += 2;
    if (l["adverse_reactions"] || l["warnings"]) s += 1;
    return s;
  };
  const best = labels.filter((l) => nameScore(l) > 0).sort((a, b) => score(b) - score(a))[0];
  return best ?? null;
}

function text(label: FdaLabel, fields: string[]) {
  for (const f of fields) {
    const v = label[f];
    if (Array.isArray(v) && typeof v[0] === "string" && v[0].trim()) {
      const t = v[0].replace(/\s+/g, " ").trim();
      return t.length > SECTION_LIMIT ? `${t.slice(0, SECTION_LIMIT)}…` : t;
    }
  }
  return null;
}

function toResult(label: FdaLabel, query: string, matchedTerm: string, matchedBy: "name" | "active-ingredient"): MedicineLookupResult {
  const productType = label.openfda?.product_type?.[0] ?? "";
  const sections: Record<string, string> = {};
  for (const [key, fields] of Object.entries(SECTION_FIELDS)) {
    const value = text(label, fields);
    if (value) sections[key] = value;
  }
  const eff = label.effective_time;
  return {
    found: true,
    query,
    matchedBy,
    matchedTerm,
    brandNames: (label.openfda?.brand_name ?? []).slice(0, 3),
    genericName: label.openfda?.generic_name?.[0] ?? null,
    manufacturer: label.openfda?.manufacturer_name?.[0] ?? null,
    prescriptionStatus: /PRESCRIPTION/i.test(productType)
      ? "Prescription only"
      : /OTC/i.test(productType)
        ? "Over-the-counter"
        : "Not stated in label",
    routes: label.openfda?.route ?? [],
    sections,
    source: {
      name: "U.S. FDA drug label (openFDA / DailyMed)",
      url: label.set_id
        ? `https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=${label.set_id}`
        : "https://open.fda.gov/apis/drug/label/",
      lastUpdated: eff && eff.length === 8 ? `${eff.slice(0, 4)}-${eff.slice(4, 6)}-${eff.slice(6, 8)}` : null,
    },
  };
}

async function lookupOne(term: string) {
  const core = coreName(term) || term.toLowerCase();
  const ingredients = await normalizeWithRxNorm(core);
  const labels = await searchFda(ingredients, core);
  return pickBest(labels, ingredients, core);
}

export async function lookupMedicine(name: string, activeIngredient?: string | null): Promise<MedicineLookupResult> {
  const query = sanitizeMedicineName(name);
  if (query.length < 2) {
    return { found: false, query, reason: "Please enter a valid medicine name." };
  }
  try {
    const direct = await lookupOne(query);
    if (direct) return toResult(direct, query, query, "name");

    const alt = activeIngredient ? sanitizeMedicineName(activeIngredient) : "";
    if (alt.length >= 2 && alt.toLowerCase() !== query.toLowerCase()) {
      const viaIngredient = await lookupOne(alt);
      if (viaIngredient) return toResult(viaIngredient, query, alt, "active-ingredient");
    }
    return {
      found: false,
      query,
      reason:
        "No verified drug label was found for this name in the FDA database. It may be a regional brand name, spelled differently, or not listed.",
    };
  } catch (error) {
    console.error("Medicine lookup failed", error);
    return {
      found: false,
      query,
      reason: "The medicine information service could not be reached right now. Please try again shortly.",
    };
  }
}
